"""Local review page references raw captures; images are never retouched or upscaled."""
from pathlib import Path
import csv,json,html
root=Path(__file__).resolve().parents[1];out=root/'Docs/Diagnostics/Phase7B'
def figure(path,label):
    return f'<figure><a href="{path}" target="_blank"><img loading="lazy" src="{path}" alt="{html.escape(label)}"></a><figcaption>{html.escape(label)} · open original PNG</figcaption></figure>'
def pair(title,a,b,note=''):
    return f'<section><h2>{title}</h2><p>{note}</p><div class="pair">{figure(*a)}{figure(*b)}</div></section>'
body=pair('Town materials and architecture',('Before/town.png','Before · Phase 7A'),('After/town.png','After · Phase 7B'),'Matched overview camera, raw 1920 × 1080 editor renders. Doorways, functional targets and compact collision boundary are retained.')
body+=pair('Hands at rest',('Before/host-fp-hud-minimap.png','Before · original Sunny fists'),('Targeted1080/host-hands-rest-fov-74.png','After · refined owner-local hands, FOV 74'),'Actual Windows player captures. Locations differ; compare hand proportions and screen occupation.')
body+=pair('Carrying a sanitation bag',('Before/client-fp-carry-bag.png','Before · carried bag'),('Targeted1080/client-hands-carry-bag.png','After · carried bag'),'Actual carried object and authoritative holder state. No additional hand camera.')
body+=pair('Visible crate grip and wide FOV',('Targeted1080/host-hands-carry-crate.png','After · crate grip'),('Targeted1080/host-hands-rest-fov-95.png','After · idle at FOV 95'),'The crate remains the real multiplayer object; the local rig follows its grip points. User comfort still needs a keyboard/mouse session.')
body+=pair('Personal map marker lifecycle',('Targeted1080/host-minimap-before-inspection.png','Two active inspections'),('Targeted1080/host-minimap-after-inspection.png','Completed inspection removed'),'Same role, successive authoritative task states. Locked repair previews have no blue map pin. No colleague private work is shown.')
body+=pair('Day and evening',('After/street-day.png','Day · clouds and warm town materials'),('After/street-night.png','Evening · blue sky, warm street lamps'),'Controlled editor previews through production atmosphere Apply; runtime phase uses synchronized NGO server time. Clouds, lamps and windows share that phase.')
body+=pair('Remote multiplayer body presentation',('Before/client-remote-host-walking.png','Before · remote walk'),('Targeted1080/client-remote-walk.png','After · remote walk'),'Actual two-process NGO captures; use the controlled cycles below to compare contact through every animation frame.')
body+='<section><h2>Walk and run contact through the cycle</h2><p>Controlled raw Unity renders of the original Sunny rig, original clips and final bone-only derivative clips. Production speeds (2.2 / 4.2 m/s) and serialized cadence; camera follows the character over stationary reference lines. This is animation inspection, separate from the multiplayer captures above.</p><button id="play">Pause slow motion</button> <label>Cycle pose <input id="pose" type="range" min="0" max="23" value="0"></label><p>Playback is 0.25× production speed. Scrubbing compares normalized cycle phases.</p><div class="pair">'
for label in ['Phase7A-Walk','Phase7B-Walk','Phase7A-Run','Phase7B-Run']:
    body+=f'<figure><img class="cycle" data-clip="{label}" src="Animation/{label}/00.png" alt="{label}"><figcaption>{label}</figcaption></figure>'
body+='</div><p>Sampled middle-stance horizontal ankle drift: walk 0.970 m → 0.00048 m; run 0.437 m → 0.00318 m. Both clips use the shared player hierarchy, and actual player Animator bone motion is checked separately. This measures the left ankle, not every sole vertex, turn, landing or human perception. Sunny’s short legs require a quick cartoon cadence. Review that cadence in motion.</p></section>'
body+=pair('Native output and remote running',('Targeted1080/host-native-1920x1080.png','Native Windows 1080p'),('Targeted1080/client-remote-run.png','Remote run, actual NGO player'),'Both quality presets are checked at 1280 × 720 and 1920 × 1080 using the actual URP camera target descriptor, with render scale 1 and dynamic resolution off. Screenshot dimensions alone are not the verification.')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Business as Usual — Phase 7B Review</title><style>
*{box-sizing:border-box}body{margin:0;background:#efe7d1;color:#243f42;font:17px/1.55 system-ui,sans-serif}main{max-width:1320px;margin:auto;padding:32px}header{border-bottom:4px solid #243f42;padding:8px 0 24px}h1{font-size:42px;line-height:1.15}h2{font-size:25px}section{padding:24px 0;border-bottom:1px solid #9ea393}.pair{display:grid;grid-template-columns:1fr 1fr;gap:18px}figure{margin:0;background:#f8efda;border:2px solid #243f42}img{width:100%;height:auto;display:block}figcaption{padding:10px 14px;font-size:14px}button{background:#243f42;color:#f8efda;border:0;padding:10px 16px;font:inherit;cursor:pointer}a{color:inherit}input{vertical-align:middle}p{max-width:1000px}.tag{letter-spacing:.13em;font-weight:700;font-size:13px}@media(max-width:800px){.pair{grid-template-columns:1fr}main{padding:18px}h1{font-size:32px}}</style><main><header><div class="tag">BUSINESS AS USUAL / REVIEW COPY</div><h1>Phase 7B — a living town foundation</h1><p>Raw evidence and inspection previews. Meshy: 75 / 300 cumulative credits. New job systems, AI and criminal mechanics remain design proposals.</p><p><a href="../../Design/phase8-living-town-proposal.md">Gameplay audit and Phase 8 proposal</a> · <a href="validation-summary.json">Validation results</a> · <a href="preservation.json">Source and staging preservation</a></p></header>'''+body+'''<footer><p>Automated evidence is not a human playtest. Open the build to judge hand comfort, cadence, lighting and readability; cross-machine LAN usability has not been human verified.</p></footer></main><script>
const cycles=[...document.querySelectorAll('.cycle')],duration={'Phase7A-Walk':1.333333/1.45,'Phase7B-Walk':.333333/1.6923077,'Phase7A-Run':1/1.85,'Phase7B-Run':.2666667/1.4};let playing=true,start=performance.now();for(const img of cycles)for(let i=0;i<24;i++){let p=new Image();p.src=`Animation/${img.dataset.clip}/${String(i).padStart(2,'0')}.png`;}function show(img,frame){img.src=`Animation/${img.dataset.clip}/${String(frame).padStart(2,'0')}.png`;}document.querySelector('#play').onclick=e=>{playing=!playing;e.target.textContent=playing?'Pause slow motion':'Play slow motion';start=performance.now();};document.querySelector('#pose').oninput=e=>{playing=false;document.querySelector('#play').textContent='Play slow motion';cycles.forEach(img=>show(img,Number(e.target.value)));};function tick(now){if(playing)cycles.forEach(img=>show(img,Math.floor(((now-start)/1000*.25/duration[img.dataset.clip]%1)*24)));requestAnimationFrame(tick);}requestAnimationFrame(tick);
</script></html>'''
(out/'review.html').write_text(page,encoding='utf-8')
for file,key in [(out/'map-validation.csv','checks'),(out/'After/atmosphere-validation.csv','checks'),(out/'Animation/prefab-binding-validation.csv','checks')]:
    checks=[dict(name=r['name'],passed=r['passed'].lower()=='true') for r in csv.DictReader(file.open())]
    file.with_suffix('.json').write_text(json.dumps({key:checks},indent=2))
samples=[dict(clip=r['clip'],**{k:float(v) for k,v in r.items() if k!='clip'}) for r in csv.DictReader((out/'Animation/imported-stance-validation.csv').open())]
(out/'Animation/imported-stance-validation.json').write_text(json.dumps(dict(method='101 samples in middle left-ankle stance on final Unity clips plus authoritative travel; root transform tracks removed from final derivatives. Not a whole-sole or human gait assessment.',samples=samples),indent=2))
print('Wrote raw-image review page and CSV-derived verification reports')
